long long power(long long a, long long b, long long m) {   // a^b mod m за O(log b)
    long long r = 1;
    a %= m;
    while (b > 0) {
        if (b & 1) r = r * a % m;
        a = a * a % m;
        b >>= 1;
    }
    return r;
}
